old=" async function examplesAiGenerate(query){\n  if(examplesAiBusy)return;\n  var rec=match(query),data=rec&&rec.data||{},inf=data.infinitive||{};\n  var order=['present','past','future','imperative'];\n  var forms={};\n  order.forEach(function(tense){forms[tense]=(Array.isArray(data[tense])?data[tense]:[]).map(function(r){return r&&r.he||'';}).filter(Boolean);});\n  if(order.some(function(t){return !forms[t].length;})){\n   examplesAiNotice('Для автоматических примеров необходимо полное спряжение выбранного глагола.');return;\n  }\n  examplesAiBusy=true;\n  var ai=el('alwaysAiCodeAI');if(ai)ai.setAttribute('aria-busy','true');\n  examplesAiNotice('AI создаёт примеры…');\n  var rows={},used={};\n  try{\n   for(var i=0;i<order.length;i++){\n    var tense=order[i];\n    var labels={present:'настоящем времени',past:'прошедшем времени',future:'будущем времени',imperative:'повелительном наклонении'};\n    var found=null,lastError='';\n    for(var attempt=0;attempt<3&&!found;attempt++){\n     var sample=forms[tense].slice(attempt===0?0:attempt===1?3:0,attempt===0?4:attempt===1?7:8).join(', ');\n     var topic='Составь 5 коротких предложений на иврите с глаголом '+(inf.he||query)+'. Время: '+labels[tense]+'. Используй эти формы с огласовками: '+sample+'. Переводы ru, uk, en.';\n     try{\n      var response=await fetch('/api/ai/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({section:'examples',topic:topic,level:'beginner'}),cache:'no-store'});\n      if(!response.ok){lastError='HTTP '+response.status;continue;}\n      var result=await response.json(),items=result&&result.sentences;\n      if(!Array.isArray(items)){lastError='Ответ AI не содержит предложений';continue;}\n      found=items.find(function(r){return r&&['he','ru','uk','en'].every(function(k){return typeof r[k]==='string'&&r[k].trim();})&&examplesAiMatches(r.he,forms[tense])&&!used[examplesAiWords(r.he).join(' ')];});\n      if(!found)lastError='Нет проверенной формы глагола';\n     }catch(e){lastError=String(e&&e.message||e);}\n    }\n    if(!found)throw Error('Не получен пример для '+labels[tense]+': '+lastError);\n    rows[tense]={he:found.he,ru:found.ru,uk:found.uk,en:found.en};\n    used[examplesAiWords(found.he).join(' ')]=true;\n   }\n   if(!document.body.classList.contains('independent-examples-mode')||!el('verbSearch')||el('verbSearch').value.trim()!==query)return;\n   render(order.map(function(t){return rows[t];}));displayed=true;\n  }catch(error){\n   examplesAiNotice('Не удалось создать четыре правильных примера: '+(error&&error.message||error));\n  }finally{examplesAiBusy=false;if(ai)ai.removeAttribute('aria-busy');}\n }\n"
new=" var examplesAiReady=null;\n function examplesAiSpinner(active){\n  var b=el('alwaysAiCodeAdd');if(!b)return;\n  b.classList.toggle('examples-ai-loading',!!active);\n  if(active)b.setAttribute('aria-busy','true');else b.removeAttribute('aria-busy');\n }\n async function examplesAiGenerate(query){\n  if(examplesAiBusy)return;\n  var rec=match(query),data=rec&&rec.data||{},inf=data.infinitive||{};\n  var order=['present','past','future','imperative'],forms={};\n  order.forEach(function(t){forms[t]=(Array.isArray(data[t])?data[t]:[]).map(function(r){return r&&r.he||'';}).filter(Boolean);});\n  if(order.some(function(t){return !forms[t].length;})){\n   examplesAiNotice('Для автоматических примеров необходимо полное спряжение выбранного глагола.');return;\n  }\n  examplesAiReady=null;examplesAiBusy=true;examplesAiSpinner(true);\n  examplesAiNotice('AI создаёт примеры…');\n  try{\n   var labels={present:'настоящее',past:'прошедшее',future:'будущее',imperative:'повелительное наклонение'};\n   var instructions=order.map(function(t){return labels[t]+': '+forms[t].slice(0,5).join(', ');}).join('; ');\n   var topic='Глагол '+(inf.he||query)+'. Составь ровно четыре коротких разных предложения на иврите с огласовками: 1 настоящее, 2 прошедшее, 3 будущее, 4 повелительное наклонение. Для каждой формы используй одну из точных форм спряжения: '+instructions+'. Обязательно дай переводы ru, uk, en для каждого предложения. Верни четыре предложения в этом порядке.';\n   var response=await fetch('/api/ai/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({section:'examples',topic:topic,level:'beginner'}),cache:'no-store'});\n   if(!response.ok)throw Error('HTTP '+response.status+(response.status===429?' — лимит ИИ исчерпан, повторите позже':''));\n   var result=await response.json(),items=result&&result.sentences;\n   if(!Array.isArray(items))throw Error('Ответ ИИ не содержит предложений');\n   var used={},rows=[];\n   order.forEach(function(t){\n    var found=items.find(function(r){\n     if(!r||!['he','ru','uk','en'].every(function(k){return typeof r[k]==='string'&&r[k].trim();}))return false;\n     var key=examplesAiWords(r.he).join(' ');\n     return !used[key]&&examplesAiMatches(r.he,forms[t]);\n    });\n    if(found){used[examplesAiWords(found.he).join(' ')]=true;rows.push({he:found.he,ru:found.ru,uk:found.uk,en:found.en});}\n   });\n   if(rows.length!==4)throw Error('ИИ вернул не все четыре проверенные формы ('+rows.length+' из 4). Повторите запрос позже.');\n   if(!document.body.classList.contains('independent-examples-mode')||!el('verbSearch')||el('verbSearch').value.trim()!==query)return;\n   examplesAiReady={query:query,rows:rows};\n   examplesAiNotice('Готово. Нажмите +, чтобы открыть четыре примера.');\n  }catch(error){\n   examplesAiNotice('Не удалось подготовить примеры: '+(error&&error.message||error));\n  }finally{examplesAiBusy=false;examplesAiSpinner(false);}\n }\n"
